/* WHOLE_DRIVER_CANDIDATE fn_000000000001b280 origin=model_output original=wdr_mode */
int32_t wdr_mode(void *ctx, int32_t value, char direction, int32_t *result)
{
    /*
     * OEM T10 module 0x1a1a0 (same Apical 3.12 firmware as T20): ctx is the API context
     * (fw_ctx + 0x18) and ctx + 0x14e8 is general_fsm.p_fsm_mgr, which is
     * *loaded* to reach the FSM manager:
     *
     *     SET 14/15: mgr[0x1527] = 0/1, ctx[0x1528] = 0, return 0
     *     GET:       mgr[0x1524] 0 -> 14, 1 -> 15, else return 5
     *
     * The earlier reconstruction stored 0 to ctx + 0x14e8 instead.  That
     * NULLed general_fsm.p_fsm_mgr on the first WDR_MODE_ID set (tuning
     * open applies the WDR control whenever ispmem leaves room for the WDR
     * buffer, e.g. T10 ispmem=8M), and the next calibration update
     * (day/night) read NULL + 0x1524 in apical_api_calibration().
     */
    uint32_t dir = (uint32_t)(uint8_t)direction;
    uint8_t *mgr = *(uint8_t **)((uintptr_t)ctx + 0x14e8);
    uint8_t cur;

    *result = 0;
    if (dir == 0) {
        if (value != 14 && value != 15) {
            *result = 1;
            return 5;
        }
        if (!mgr)
            return 5;
        mgr[0x1527] = value == 15;
        *(uint8_t *)((uintptr_t)ctx + 0x1528) = 0;
        return 0;
    }
    if (dir != 1) {
        *result = 1;
        return 5;
    }
    if (!mgr)
        return 5;
    cur = mgr[0x1524];
    if (cur == 0) {
        *result = 14;
        return 0;
    }
    if (cur == 1) {
        *result = 15;
        return 0;
    }
    return 5;
}

/* WHOLE_DRIVER_CANDIDATE fn_000000000001b308 origin=fragment_seed original=histogram_lum */
int32_t histogram_lum(uintptr_t ctx_addr, uint32_t value, uint32_t direction, uintptr_t ret_addr)
{
	/* OEM 0x1a9a8: only GET (1) is valid (else status 1); it requests a
	 * histogram dump (AE hist_request = 1, buffer size 0) with interrupts off
	 * unless fw->irq_locked is set, *ret = 0, status 0 */
	struct t20_isp_ctx *isp = (struct t20_isp_ctx *)ctx_addr;
	struct t20_fw_outer *fw = isp->fw;

	if ((direction & 0xff) != 1)
		return 1;
	if (fw->irq_locked == 0)
		system_hw_interrupts_disable();
	apical_api_buffer_data_size = 0;
	isp->ae.hist_request = 1;
	if (isp->fw->irq_locked == 0)
		system_hw_interrupts_enable();
	*(uint32_t *)ret_addr = 0;
	return 0;
}

