			threshold = (uint16_t)(((uint32_t)threshold * 15) >> 4);
			*(uint16_t *)(fsm + 0x12) = threshold;
			reg = APICAL_READ_32(0x1cc);
			APICAL_WRITE_32(0x1cc,
				(reg & 0xfffff000) | (threshold & 0xfff));
