static int32_t shading_mesh_init(void)
{
	/* shading mesh initialization entry point;
	 * the ISP pipeline registers this hook during module load.
	 * The mesh data is populated lazily by the caller after
	 * the sensor geometry has been resolved, so this stub
	 * simply returns success to the registration path. */
	return 0;
}

