int16_t *matrix_compute_hue_saturation(int32_t angle, int16_t *out)
{
	int16_t sin_lut[91];
	int16_t coefficients[27];
	uint32_t hue = ((uint32_t)angle - 0xb4) & 0xffff;
	int32_t idx1, idx2;
	int32_t sign1, sign2;
	int32_t coeff1, coeff2;
	unsigned int i;

	/* T20 OEM .rodata +0x24b0/+0x2568/+0x25a0.  The same
	 * byte-indexed implementation is used by the working T30/T21 path. */
	memcpy(sin_lut, (void *)((char *)&v_filter + 0x400), sizeof(sin_lut));
	memcpy(coefficients, (void *)((char *)&v_filter + 0x4b8),
	       sizeof(coefficients));
	memcpy(out, t20_matrix_yuv_src, sizeof(t20_matrix_yuv_src));

	if (hue < 0x5b) {
		idx1 = (int8_t)hue;
		sign1 = 1;
	} else if ((uint32_t)angle - 0x10f < 0x5a) {
		idx1 = (int8_t)(-76 - hue);
		sign1 = -1;
	} else if ((uint32_t)angle - 0x5a >= 0x5a) {
		if ((uint32_t)angle >= 0x5a) {
			idx1 = 0;
			sign1 = 0;
		} else {
			idx1 = (int8_t)(hue - 76);
			sign1 = -1;
		}
	} else {
		idx1 = (int8_t)(-hue);
		sign1 = 1;
	}

	if (hue < 0x5b) {
		idx2 = (int8_t)(0x5a - hue);
		sign2 = 1;
	} else if ((uint32_t)angle - 0x10f < 0x5a) {
		idx2 = (int8_t)(hue - 0x5a);
		sign2 = 1;
	} else if ((uint32_t)angle >= 0x5a) {
		if ((uint32_t)angle - 0x5a >= 0x5a) {
			idx2 = 0;
			sign2 = 0;
		} else {
			idx2 = (int8_t)(hue + 0x5a);
			sign2 = -1;
		}
	} else {
		idx2 = (int8_t)(-90 - hue);
		sign2 = -1;
	}

	idx1 = clamp(idx1, 0, 90);
	idx2 = clamp(idx2, 0, 90);
	coeff1 = (int16_t)((uint16_t)sin_lut[idx1] * sign1);
	coeff2 = (int16_t)((uint16_t)sin_lut[idx2] * sign2);

	for (i = 0; i < 9; i++) {
		int32_t value = (int32_t)coefficients[i * 3] >> 1;

		value += ((int32_t)coefficients[i * 3 + 1] * coeff1) >> 15;
		value += ((int32_t)coefficients[i * 3 + 2] * coeff2) >> 15;
		out[i] = (int16_t)value >> 5;
	}

	return out + 9;
}

