int32_t update_composite_matrix(void *src_matrix, void *dst_matrix)
{
	const int16_t *src = src_matrix;
	int16_t *dst = dst_matrix;
	int16_t product[9];
	int16_t offsets[3];
	unsigned int row, column, k;

	for (row = 0; row < 3; row++) {
		for (column = 0; column < 3; column++) {
			int32_t sum = 0;

			for (k = 0; k < 3; k++)
				sum += ((int32_t)src[row * 3 + k] *
					(int32_t)dst[k * 3 + column]) >> 8;
			product[row * 3 + column] = (int16_t)sum;
		}
	}

	for (row = 0; row < 3; row++) {
		int32_t sum = 0;

		for (k = 0; k < 3; k++)
			sum += ((int32_t)src[row * 3 + k] *
				(int32_t)dst[9 + k]) >> 8;
		offsets[row] = (int16_t)sum;
	}

	memcpy(dst, product, sizeof(product));
	for (row = 0; row < 3; row++) {
		int32_t value = clamp((int32_t)offsets[row], -1023, 1023);

		dst[9 + row] = (int16_t)value + src[9 + row];
	}

	return 6;
}

