	/* Exact OEM stores at 0x27308-0x27324. */
	fsm->field_e0 = 0x1a5e0;
	fsm->calibrate_count_de = 0;
	fsm->field_e4 = 0;
	fsm->field_e6 = 0x438;
	fsm->field_f0 = 0;
	fsm->field_f2 = 0;
	return 0x438;
