/* WHOLE_DRIVER_CANDIDATE fn_00000000000273ac origin=model_output original=sensor_fsm_switch_state */
uint32_t sensor_fsm_switch_state(int32_t *fsm_ptr, int32_t new_state)
{
	struct t20_fsm_sensor *fsm = (struct t20_fsm_sensor *)fsm_ptr;
	int32_t old_state = fsm->hdr.state;
	uint32_t result;

	if (new_state == old_state)
		return old_state;

	fsm->hdr.state = new_state;

	if (old_state >= 3) {
		if (old_state == 3)
			sensor_stop_calibrate();
		if (new_state < 3) {
			apical_isp_raise_event(fsm->hdr.isp, 0x10);
			result = 2;
		} else {
			result = 3;
		}
	} else if (new_state < 3) {
		result = 2;
	} else {
		apical_isp_raise_event(fsm->hdr.isp, 0xf);
		result = 3;
	}

	if (new_state == 2) {
		uint8_t count;

		sensor_update_black(fsm_ptr);
		count = fsm->calibrate_count_de;
		if (count)
			fsm->calibrate_count_de = count - 1;
		else
			apical_isp_raise_event(fsm->hdr.isp, 0xc);

		result = 1;
		if (fsm->field_f0 == 1) {
			result = apical_isp_raise_event(fsm->hdr.isp, 0x11);
			fsm->field_f0 = 0;
		}
	}

	if (new_state == 3) {
		fsm->field_d4 = 0xa;
		sensor_start_calibrate();
		return 0;
	}

	result = 5;
	if (new_state == 4) {
		result = sensor_hw_init(fsm_ptr);
		fsm->field_d8 = 0;
	} else if (new_state == 5) {
		return sensor_sw_init(fsm_ptr);
	}

	return result;
}

/* WHOLE_DRIVER_CANDIDATE fn_0000000000027540 origin=model_output original=sensor_fsm_process_state */
uint32_t sensor_fsm_process_state(int32_t *fsm_ptr)
{
	struct sensor_fsm *fsm = (struct sensor_fsm *)fsm_ptr;
	int32_t state = t20_hdr(fsm_ptr)->state;
	void (*switch_fn)(struct sensor_fsm *, int32_t) = sensor_fsm_switch_state;
	int32_t new_state;

	for (;;) {
		int32_t idx = state - 1;

		if ((uint32_t)idx >= 6u)
			return 0;

		switch (idx) {
		case 0:
			state = 0;
			if (fsm->field_d8 == 0)
				continue;
			new_state = 6;
			break;
		case 1:
		case 4:
			new_state = 1;
			break;
		case 2:
			if (fsm->field_d4 != 0)
				return fsm->field_d4;
			new_state = 1;
			break;
		case 3:
			new_state = 5;
			break;
		case 5:
			if (fsm->field_d8 != 0)
				continue;
			new_state = 1;
			break;
		}

		switch_fn(fsm, new_state);
		state = new_state;
	}
}

/* WHOLE_DRIVER_CANDIDATE fn_0000000000027604 origin=model_output original=sensor_fsm_process_event */
int32_t sensor_fsm_process_event(int32_t *fsm_ptr, int32_t event)
{
	struct t20_fsm_hdr *fsm = t20_hdr(fsm_ptr);
	struct sensor_fsm *sfsm = (struct sensor_fsm *)fsm_ptr;
	int32_t state;
	int32_t next;

	/* every handled event leaves the loop with the next state set */
	do {
		if (event == 11) {
			state = fsm->state;
			if (state == 1) {
				sensor_load_vars();
				next = 2;
				continue;
			} else if (state == 2) {
				sfsm->field_d4 -= 1;
				next = 3;
				continue;
			} else {
				return 0;
			}
		} else if ((uint32_t)event < 12u) {
			if (event != 3)
				return 0;
			state = fsm->state;
			if (state == 1) {
				APICAL_WRITE_32(0x130, APICAL_READ_32(0x130) & 0xfffffff8);
				next = 4;
				continue;
			} else {
				return 0;
			}
		} else if (event == 14) {
			state = fsm->state;
			if (state == 1) {
				next = 3;
				continue;
			} else {
				return 0;
			}
		} else {
			if (event != 17)
				return 0;
			state = fsm->state;
			if (state == 1) {
				next = 5;
				continue;
			} else {
				return 0;
			}
		}
	} while (0);

	sensor_fsm_switch_state(fsm_ptr, next);
	sensor_fsm_process_state(fsm_ptr);
	return 1;
}

