	fsm->field_18 = 256;
	fsm->exposure_log2 = 131072;
	fsm->field_48 = 41;
	fsm->history_index = (uint32_t)-1;
	fsm->antiflicker_freq = 12800;
	fsm->field_1bc = 64;
	fsm->exposure_ratio = 64;
	fsm->field_10 = 0;
	fsm->field_1c4 = 0;
	fsm->field_1c6 = 0;
	fsm->field_1c8 = 0;
	fsm->isp_dgain_log2 = 0;
	fsm->field_1d8 = 0;

