		cmos_fsm_process_state(fsm_ptr);
		return 1;
	case 3:
	case 4:
	case 6:
	case 7:
	case 9:
	case 0xa:
	case 0xb:
	case 0xc:
	case 0xd:
	case 0xe:
		return 0;
	case 5:
