/* WHOLE_DRIVER_CANDIDATE fn_000000000002b3e0 origin=model_output original=ae_initialize */
int32_t ae_initialize(int32_t *fsm)
{
    uint32_t i = 0x1e00;
    uint32_t row_end;
    uint32_t word_addr;
    uint32_t shift;
    uint32_t mask;
    uint32_t val;
    uint32_t new_val;

    do {
        row_end = i + 0xf;
        word_addr = i & 0xfffffffc;
        do {
            shift = (i & 3) << 3;
            i++;
            val = APICAL_READ_32(word_addr);
            mask = ~(0xff << (shift & 0x1f));
            new_val = (val & mask) | (0xf << (shift & 0x1f));
            APICAL_WRITE_32(word_addr, new_val);
            word_addr = i & 0xfffffffc;
        } while (i != row_end);
    } while (i != 0x1ee1);

    fsm[3] = 8;
    return AE_request_interrupt(fsm, 8);
}

/* WHOLE_DRIVER_CANDIDATE fn_000000000002b4c8 origin=fragment_seed original=ae_read_full_histogram_data */
uint32_t ae_read_full_histogram_data(uintptr_t ae_addr)
{
	/* OEM 0x2b4c8.  The OEM function is void; the value it leaves in v0
	 * (the dump request flag, or the address of the size variable after a
	 * dump) is returned unchanged because the AE trace prints it. */
	struct t20_fsm_ae *ae = (struct t20_fsm_ae *)ae_addr;
	uint32_t *api_buffer = (uint32_t *)(uintptr_t)get_apical_api_buffer();
	uint32_t total = 0;
	uint32_t result;
	uint32_t bin;

	/* statistics memory at 0x10000: 12-bit mantissa, 4-bit exponent */
	for (bin = 0; bin != 256; bin++) {
		uint32_t word = APICAL_READ_32((bin << 2) + 0x10000);
		uint32_t exponent = (word >> 12) & 15;
		uint32_t count = word & 4095;

		if (exponent != 0)
			count = (count | 4096) << (exponent - 1);
		ae->hist[bin] = count;
		total += count;
	}

	result = ae->hist_request;
	ae->hist_total = total;
	if (result != 0) {
		/* histogram_lum() asked for a copy in the API buffer */
		ae->hist_request = 0;
		for (bin = 0; bin != 256; bin++)
			api_buffer[bin] = ae->hist[bin];
		apical_api_buffer_data_size = sizeof(ae->hist);
		result = (uintptr_t)&apical_api_buffer_data_size;
	}
	return result;
}

static u32 t20_ae_metered_mean(int32_t *ae, u32 highlight_tail)
{
	u64 weighted = 0;
	u32 population = 0;
	u32 tail_start;
	u32 i;

	highlight_tail = min_t(u32, highlight_tail, 256);
	tail_start = 256 - highlight_tail;
	for (i = 0; i < 256; i++) {
		u32 count = *(u32 *)((u8 *)ae + 0x30 + i * sizeof(u32));
		u32 weight = 1;

		/* Match the OEM half-step bin centres and IQ-selected highlight tail. */
		if (i >= tail_start) {
			weight = (i + highlight_tail - 254) >> 1;
			if (!weight)
				weight = 1;
		}
		population += count;
		weighted += (u64)count * (2 * i + 1) * weight;
	}
	if (!population)
		return 0;
	return (u32)div64_u64(weighted, (u64)population * 2);
}

static u8 t20_ae_exposure_correction(u8 wdr_mode, u32 exposure_q6)
{
	int correction_index = _GET_HDR_TABLE_INDEX(
		T20_CAL_AE_CORRECTION_START, wdr_mode);
	u32 correction_len = _GET_LEN(correction_index);
	u32 exposure_len = _GET_LEN(T20_CAL_AE_EXPOSURE_CORRECTION);
	const u8 *correction;
	const u32 *exposure;
	u32 i;

	if (_GET_WIDTH(correction_index) != sizeof(*correction) ||
	    _GET_WIDTH(T20_CAL_AE_EXPOSURE_CORRECTION) != sizeof(*exposure) ||
	    !correction_len || correction_len != exposure_len)
		return 0x80;
	correction = (void *)(uintptr_t)_GET_UCHAR_PTR(correction_index);
	exposure = (void *)(uintptr_t)_GET_UINT_PTR(
		T20_CAL_AE_EXPOSURE_CORRECTION);
	if (!correction || !exposure)
		return 0x80;
	if (exposure_q6 <= exposure[0])
		return correction[0];
	for (i = 1; i < exposure_len; i++) {
		u32 low = exposure[i - 1];
		u32 high = exposure[i];
		s32 value = correction[i - 1];

		if (exposure_q6 >= high)
			continue;
		if (high != low) {
			s32 span = high - low;
			s32 position = exposure_q6 - low;
			s32 slope = (s32)correction[i] - value;

			/* Keep a falling IQ curve in signed arithmetic. */
			value += slope * position / span;
		}
		return clamp_t(s32, value, 0, 0xff);
	}
	return correction[exposure_len - 1];
}

/*
 * #267: optional guard against a one-LSB flip of the AE correction curve
 * (t20_ae_curve_hysteresis(), tx_isp_t20_ae_max.h).  Not OEM behaviour:
 * BEYOND VENDOR, default on by user decision 2026-11-11 (docs/BEYOND_VENDOR.md);
 * t20_ae_flip_guard=0 restores the vendor behaviour.
 */
static bool t20_ae_flip_guard = true;
module_param(t20_ae_flip_guard, bool, 0644);
MODULE_PARM_DESC(t20_ae_flip_guard,
	"hold a one-step AE correction-curve change until the exposure moved 1/16 stop (beyond vendor, default on; 0 = vendor)");
static struct t20_ae_curve_hold t20_ae_curve_held;

static u32 t20_ae_corrected_target(u32 target, s32 exposure_log2,
				   u8 wdr_mode, u8 *curve_value)
{
	u32 exposure_q6 = math_exp2(exposure_log2, 16, 6);
	u8 curve = t20_ae_exposure_correction(wdr_mode, exposure_q6);
	s32 target_log2;

	if (t20_ae_flip_guard)
		curve = t20_ae_curve_hysteresis(&t20_ae_curve_held, curve,
						exposure_log2);
	else
		t20_ae_curve_held.valid = 0;
	if (curve_value)
		*curve_value = curve;
	/* Both signed offsets are IQ/system-table values in 1/32-stop units. */
	target_log2 = log2_fixed_to_fixed(target, 0, 16) +
		(((s32)stab.global_ae_compensation - 0x80) << 11) +
		(((s32)curve - 0x80) << 11);
	return max_t(u32, 1, math_exp2(target_log2, 16, 0));
}

/*
 * Compact AE/NR/Iridix controller state.  It must follow the firmware context:
 * apical_init() rebuilds that context (and the ISP register defaults) on every
 * core init, i.e. on every streamer start, while these values used to survive
 * until the module was unloaded.  A restart then resumed the previous stream's
 * exposure, cooldown and "already initialised" flags against a reset context.
 */
static unsigned int ae_irq_trace_count;
static int32_t simple_exposure_log2 = -1;
static uint8_t simple_cooldown;
static unsigned int simple_updates;
static bool simple_nr_initialized;
static bool simple_iridix_initialized;
static unsigned int simple_trace_count;
static unsigned int iq_trace_count;

/*
 * openimp #284 L5: a day/night IQ swap loads a new correction curve; the
 * held value of the old curve must not survive it (the hold would keep the
 * old one-LSB value until the exposure moves 1/16 stop, at night with the
 * exposure at its cap possibly for good).  Called after the swap.
 */
void tx_isp_t20_ae_curve_hold_reset(void)
{
	t20_ae_curve_held.valid = 0;
}

static void t20_compact_ae_reset(void)
{
	ae_irq_trace_count = 0;
	simple_exposure_log2 = -1;
	t20_ae_curve_held.valid = 0;
	simple_cooldown = 0;
	simple_updates = 0;
	simple_nr_initialized = false;
	simple_iridix_initialized = false;
	simple_trace_count = 0;
	iq_trace_count = 0;
	t20_ae_last_mean = 0;
	t20_ae_last_target = 0;
	t20_ae_last_raw_target = 0;
	t20_ae_last_curve = 0;
	t20_ae_last_population = 0;
	t20_ae_last_exposure_log2 = 0;
	t20_ae_last_isp_dgain_log2 = 0;
	t20_ccm_awb_updates = 0;
}

/* WHOLE_DRIVER_CANDIDATE fn_000000000002b5bc origin=model_output original=AE_fsm_process_interrupt */
int32_t AE_fsm_process_interrupt(int32_t *fsm_ptr, char irq)
{
	struct t20_fsm_ae *ae = (struct t20_fsm_ae *)fsm_ptr;
	int trace_ae = t20_trace_events && ae_irq_trace_count++ < 12;
	uint32_t result;

	if ((irq & 0xff) != 3)
		return 3;

	if (trace_ae)
		printk(KERN_INFO "T20AE irq before ae=%p isp=%p total=%u state=%d status=%08x pending=%08x\n",
		       ae, ae->hdr.isp, ae->hist_total, ae->hdr.state,
		       ae->hdr.pending_irq, ae->word_0c);
	result = ae_read_full_histogram_data((uintptr_t)ae);
	if (trace_ae)
		printk(KERN_INFO "T20AE histogram result=%08x total=%u first=%u last=%u\n",
		       result, ae->hist_total, ae->hist[0], ae->hist[255]);
	if (t20_simple_ae) {
		struct t20_isp_ctx *isp = ae->hdr.isp;
		uint32_t total = ae->hist_total;
		uint32_t integration = 0;
		uint32_t again_code = 0;
		int32_t again_log2 = 0;
		int32_t isp_dgain_log2 = 0;
		uint32_t mean = 0;
		uint32_t target = 0;
		uint32_t raw_target = 0;
		uint32_t highlight_tail = 0;
		uint32_t pi_coefficient = 0;
		uint32_t gain_accuracy = 0;
		int32_t correction;
		u8 curve_value = 0x80;
		int32_t error = 0;
		int target_table;
		bool tuning_feedback = false;

		/*
		 * The controller owns policy, not tuning.  Select the active linear/WDR
		 * AE-balanced bank and consume its PI coefficient, target, highlight-tail
		 * weighting, and gain accuracy.  If the IQ payload is absent or malformed,
		 * leave the seeded sensor exposure unchanged.
		 */
		target_table = _GET_HDR_TABLE_INDEX(T20_CAL_AE_BALANCED_START,
			isp->general.wdr_mode);
		if (_GET_WIDTH(target_table) == sizeof(u32) &&
		    _GET_ROWS(target_table) * _GET_COLS(target_table) >= 7) {
			const u32 *balanced = (void *)(uintptr_t)
				_GET_UINT_PTR(target_table);

			if (balanced) {
				pi_coefficient = balanced[0];
				raw_target = clamp_t(u32, balanced[1], 1, 255);
				highlight_tail = balanced[2];
				gain_accuracy = balanced[6];
				mean = t20_ae_metered_mean(fsm_ptr, highlight_tail);
			}
		}

		/* Seed from the active sensor attribute before applying feedback. */
		result = tx_isp_t20_simple_ae_apply(&simple_exposure_log2,
			&integration, &again_log2, &again_code, &isp_dgain_log2,
			exposure_partitions_balanced,
			ARRAY_SIZE(exposure_partition_int_priority) / 2);
		if (result == 0 && raw_target && pi_coefficient && gain_accuracy)
			target = t20_ae_corrected_target(raw_target,
				simple_exposure_log2, isp->general.wdr_mode, &curve_value);
		/*
		 * #252: the error is log2(target) - log2(mean) in Q16 like the
		 * OEM ae_calculate_target() (ae_balanced_func.c.o 0x37c-0x820),
		 * integrated with K = AE_PI_COEFF like ae_calculate_exposure()
		 * (0x928-0x9e8, (err + acc) / K per frame); the step per
		 * update, the 1-stop clamp and the deadband are in
		 * t20_ae_log2_correction() (tx_isp_t20_ae_max.h).  A black
		 * frame (mean 0) meters as 1.
		 */
		if (result == 0 && target)
			error = (int32_t)log2_fixed_to_fixed(target, 0, 16) -
				(int32_t)log2_fixed_to_fixed(max_t(u32, mean, 1),
					0, 16);
		if (result == 0 && target && simple_cooldown == 0) {
			correction = t20_ae_log2_correction(error,
				pi_coefficient);
			simple_exposure_log2 += correction;
			result = tx_isp_t20_simple_ae_apply(
				&simple_exposure_log2, &integration,
				&again_log2, &again_code, &isp_dgain_log2,
				exposure_partitions_balanced,
				ARRAY_SIZE(exposure_partition_int_priority) / 2);
			tuning_feedback = result == 0;
			simple_cooldown = 2;
			simple_updates++;
		} else if (simple_cooldown) {
			simple_cooldown--;
		}

		if (result == 0) {
			/* re-read like the OEM: the calls above may change it */
			struct t20_isp_ctx *ctx = ae->hdr.isp;
			struct tx_isp_t20_nr_state *nr =
				t20_fsm_sibling(ae, ae, noise_reduction);
			struct t20_fsm_sharpening *sharpening = &ctx->sharpening;

			/* openimp #285: like the OEM cmos_update_exposure_
			 * history(), a manual time (stab.global_manual_integration_time) / analog gain
			 * (stab.global_manual_sensor_analog_gain) keeps the value the user set in stab.global_integration_time /
			 * stab.global_sensor_analog_gain. */
			if (!stab.global_manual_integration_time)
				stab.global_integration_time = (uint16_t)integration;
			if (!stab.global_manual_sensor_analog_gain)
				stab.global_sensor_analog_gain = (uint8_t)clamp_t(int32_t,
					again_log2 >> 11, 0, 255);
			ctx->sensor.black_again_reg = again_code;
			ctx->sensor.black_again_log2 = again_log2 >> 12;
			isp->cmos.exposure_log2 = simple_exposure_log2;

			/*
			 * Publish the compact AE result through the same owner ABI used
			 * by the OEM tuning FSM.  The NR update consumes only active IQ
			 * tables; it has no sensor-name or device-specific branches.
			 */
			isp->cmos.sensor_again_log2 = again_log2;
			isp->cmos.sensor_dgain_log2 = 0;
			/*
			 * #246: publish and apply the ISP digital gain like the
			 * OEM cmos_digital_gain_update() + cmos_update_exposure_
			 * history(): the owner view feeds the NR/sharpen/LSC/
			 * saturation gain modulation, stab.global_isp_digital_gain is what isp-m0 and
			 * GetTotalGain report (OEM only when not manual, stab.global_manual_isp_digital_gain),
			 * and the cmos frame-start interrupt writes register 0x1a0
			 * (4.8) from the frame_update.isp_dgain slot of the sensor callback
			 * tuple (OEM cmos_func.c.o 0xcb8-0xd14; the interrupt-7
			 * copy into that tuple is skipped in compact mode).
			 */
			isp->cmos.isp_dgain_log2 = isp_dgain_log2;
			ctx->cmos.frame_update.isp_dgain = isp_dgain_log2;
			if (!stab.global_manual_isp_digital_gain)
				stab.global_isp_digital_gain = (uint8_t)clamp_t(int32_t,
					isp_dgain_log2 >> 11, 0, 255);
			if (isp->general.wdr_mode == 0 && !isp->cmos.exposure_ratio)
				isp->cmos.exposure_ratio = T20_EXPOSURE_RATIO_Q6_ONE;
			if (t20_simple_nr) {
				int nr_result = 0;

				nr->isp = (void *)isp;
				if (!simple_nr_initialized) {
					nr_result = noise_reduction_initialize(nr);
					if (!nr_result)
						simple_nr_initialized = true;
				}
				if (simple_nr_initialized)
					nr_result = noise_reduction_update(nr);
				if (nr_result && t20_trace_events)
					printk(KERN_WARNING
					       "T20NR update failed rc=%d\n",
					       nr_result);
			}
			/*
			 * The OEM firmware runs sharpening_update() from the
			 * sharpening FSM on every frame-end event 11, which is what
			 * applies the strength stored by SHARPENING_STRENGTH_ID
			 * (V4L2_CID_SHARPNESS) together with the gain modulation.
			 * With the firmware thread parked (default simple AWB) that
			 * event is never consumed, so the sharpness control had no
			 * effect; run the same update from here instead.
			 */
			if (t20_simple_sharpen || tx_isp_t20_fw_parked())
				sharpening_update((int32_t *)sharpening);

			/*
			 * The quarantined event worker no longer fans AE gain changes out to
			 * the tuning FSMs.  Run bounded lens-shading modulation directly and
			 * update the Iridix target from the fresh AE histogram.  The OEM
			 * frame-start IRQ owns its temporal average and hardware commit.
			 */
			{
				struct t20_fsm_color_matrix *color = &ctx->color_matrix;
				struct t20_fsm_iridix *iridix = &ctx->iridix;
				int iridix_result;

				if (tx_isp_t20_fw_parked() && !t20_ccm_awb_updates) {
					/* OEM: color_matrix_update() per event 11;
					 * includes mesh_shading_modulate_strength() */
					color_matrix_update((int32_t *)color);
					t20_ccm_frame_updates++;
				} else if (tuning_feedback) {
					mesh_shading_modulate_strength((int32_t *)color);
				}
				t20_ccm_awb_updates = 0;
				if (!simple_iridix_initialized) {
					iridix_initialize((int32_t *)iridix);
					simple_iridix_initialized = true;
				}
				/* Fresh AE histograms own the target; frame-start owns its EMA. */
				iridix_result = iridix_update((int32_t *)iridix);
				if (t20_trace_events && tuning_feedback &&
				    iq_trace_count++ < 16)
					printk(KERN_INFO
					       "T20IQ gain=%u exposure=%d lsc=%u iridix=%u target=%u state=%d event=%d\n",
					       (isp->cmos.sensor_again_log2 +
						isp->cmos.sensor_dgain_log2 +
						isp->cmos.isp_dgain_log2) >> 8,
					       isp->cmos.exposure_log2,
					       APICAL_READ_32(0x39c) & 0xffff,
					       APICAL_READ_32(0x3c4) & 0xff,
					       iridix->field_10 >> 8,
					       iridix->hdr.state, iridix_result);
			}
		}
		if (t20_trace_events && simple_trace_count++ < 32)
			printk(KERN_INFO
			       "T20AE simple mean=%u target=%u raw=%u curve=%u contrast=%u tail=%u total=%u exposure=%d int=%u again=%d code=0x%x cooldown=%u rc=%d\n",
			       mean, target, raw_target, curve_value, stab.global_ae_compensation,
			       highlight_tail, total, simple_exposure_log2, integration,
			       again_log2, again_code, simple_cooldown, result);
		t20_ae_last_mean = mean;
		t20_ae_last_target = target;
		t20_ae_last_raw_target = raw_target;
		t20_ae_last_curve = curve_value;
		t20_ae_last_population = total;
		t20_ae_last_exposure_log2 = simple_exposure_log2;
		t20_ae_last_isp_dgain_log2 = isp_dgain_log2;
		if (!t20_awb_feedback_ready) {
			/* #252: "AE stable" = inside the log2 deadband (was
			 * +-1 linear, i.e. +-10 % at comp 40, +-1.25 % at night) */
			if (target && mean && t20_ae_log2_stable(error)) {
				if (t20_awb_stable_ae_frames < 4)
					t20_awb_stable_ae_frames++;
				if (t20_awb_stable_ae_frames >= 4)
					t20_awb_feedback_ready = true;
			} else {
				t20_awb_stable_ae_frames = 0;
			}
		}
		return AE_request_interrupt(fsm_ptr, 1 << 3);
	}

	result = apical_isp_raise_event(ae->hdr.isp, 1);
	if (trace_ae)
		printk(KERN_INFO "T20AE irq raised result=%08x\n", result);
	return result;
}

