/* WHOLE_DRIVER_CANDIDATE fn_000000000002e604 origin=model_output original=awb_normalise */
/*
 * As libt20-firmware 3.12.0 awb_mesh_NBP_func.c.o awb_normalise (0x2734).
 * The recovered version shadowed the global stab with a local pointer
 * (&stab + 0xc pointed into the stack), took the gain offsets 0x31/0x32
 * relative to that instead of to stab and did byte offsets in int32_t
 * units, so the manual AWB flag (stab.global_manual_awb, +12) was never
 * seen: MANUAL and the presets 2..8 left the auto gains in place.
 *
 * arg1 is the AWB fsm: u16 sensor/static gains at +0x770..+0x776, the AWB
 * R/B gains (Q8, u16) at +0x18/+0x1a, the output gains (log2 Q16) at
 * +0x760..+0x76c. In manual mode stab.global_awb_red/blue_gain (+49/+50,
 * Q7) replace the AWB result; otherwise the AWB result is reported there.
 */
int32_t *awb_normalise(int32_t *fsm_words)
{
	struct t20_fsm_awb *awb = (struct t20_fsm_awb *)fsm_words;
	struct t20_isp_ctx *isp;
	int32_t gain[4];
	int32_t lowest;
	int32_t offset;
	int i;

	for (i = 0; i < 4; i++)
		gain[i] = log2_fixed_to_fixed(awb->static_gain[i], 8, 0x10);

	if (stab.global_manual_awb != 0) {
		gain[0] += log2_fixed_to_fixed(stab.global_awb_red_gain, 7, 0x10);
		gain[3] += log2_fixed_to_fixed(stab.global_awb_blue_gain, 7, 0x10);
		awb->red_gain = (uint16_t)(stab.global_awb_red_gain << 1);
		awb->blue_gain = (uint16_t)(stab.global_awb_blue_gain << 1);
	} else {
		gain[0] += log2_fixed_to_fixed(awb->red_gain, 8, 0x10);
		gain[3] += log2_fixed_to_fixed(awb->blue_gain, 8, 0x10);
		stab.global_awb_red_gain = (uint8_t)(awb->red_gain >> 1);
		stab.global_awb_blue_gain = (uint8_t)(awb->blue_gain >> 1);
	}

	/* shift all four so that the lowest gain lands on the sensor's
	 * black-level headroom */
	lowest = gain[0] < gain[3] ? gain[0] : gain[3];
	if (gain[1] < lowest)
		lowest = gain[1];
	if (gain[2] < lowest)
		lowest = gain[2];
	isp = awb->hdr.isp;
	offset = 0xc0000 - lowest -
		 log2_fixed_to_fixed(0x1000 - isp->sensor.field_da, 0, 0x10);
	for (i = 0; i < 4; i++)
		t20_member(awb, wb_log2[i]) = gain[i] + offset;
	if (t20_trace_events) {
		static unsigned int calls, prints;

		if (calls++ % 16 == 0 && prints++ < 40)
			printk(KERN_INFO "T20AWB normalise static=%u/%u/%u/%u awb=%u/%u out=%d/%d/%d/%d\n",
			       awb->static_gain[0], awb->static_gain[1],
			       awb->static_gain[2], awb->static_gain[3],
			       awb->red_gain, awb->blue_gain,
			       awb->wb_log2[0], awb->wb_log2[1],
			       awb->wb_log2[2], awb->wb_log2[3]);
	}
	return awb->wb_log2;
}

/*
 * Beyond vendor (T10/T20): safe anti-fog preset (V4L2 CUSTOM_ANTI_FOG
 * 0x98e903, IMP_ISP_Tuning_SetAntiFogAttr).
 *
 * Why the vendor path is not used.  The stock firmware command pair
 * (antifog_set_preset + antifog_mode, TALGORITHMS ids 0xe / 0xd) runs in the
 * ioctl thread and, in one go,
 *   - writes global_manual_iridix (stab.global_manual_iridix) and the strength (stab.global_iridix_strength_target)
 *     while the frame processing reads them,
 *   - rewrites the Iridix variance word 0x3c8 (two nibbles) with the block
 *     running, mid-frame,
 *   - on "off" restores the upper strength clamp (stab.global_maximum_iridix_strength) from the
 *     calibration table 0x5b through the table lookup (a lookup that does not
 *     find its table never returns, see iridix_control_strength_calculate),
 *     and never restores 0x3c8.
 * Bisected on the cameras: going back from manual to auto Iridix, and
 * restoring 0x3c8 with Iridix active, each hung a camera.  The lifted
 * preset also wrote into its own stack frame (fixed above).
 *
 * This path instead:
 *   - validates the level (0 off, 1 strong, 2 medium, 3 weak, else -EINVAL)
 *     and only stores it (two 32-bit words, no register or table access in
 *     the caller's context);
 *   - applies it in iridix_update(), the one owner of stab.global_manual_iridix/stab.global_iridix_strength_target,
 *     between two AE statistics runs: strength 0xff / 0xc0 / 0x80 as manual
 *     Iridix, the upper clamp raised to 0xff and remembered (restored from
 *     the remembered value, never from a table);
 *   - leaves the hardware alone when the Iridix block is off (the request
 *     is kept and counted, no effect);
 *   - "off" only undoes what this path did (manual Iridix back to the auto
 *     strength), and a manual Iridix the application chose itself is left
 *     as it was;
 *   - writes the variance nibbles (opt-in, module parameter
 *     t20_antifog_variance, default 0) from the frame-start commit of
 *     Iridix, the point that already writes the Iridix strength register,
 *     and puts the original value back on "off".
 * Device test pending (the host harness cannot reproduce the hangs).
 */
volatile uint32_t t20_antifog_level;
volatile uint32_t t20_antifog_gen;
volatile uint32_t t20_antifog_hw_want;	/* bit 8 pending, bit 9 enable, bits 0..7 value */
static uint32_t t20_antifog_seen_gen;
static uint32_t t20_antifog_on;		/* level applied by this path, 0 = none */
static uint8_t t20_antifog_saved_max;	/* stab.global_maximum_iridix_strength before the preset */
static uint8_t t20_antifog_prev_manual;	/* stab.global_manual_iridix before the preset */
static uint8_t t20_antifog_var_saved;
static uint8_t t20_antifog_var_valid;
uint32_t t20_antifog_variance;
uint32_t t20_antifog_ignored;		/* requests with the Iridix block off */
module_param(t20_antifog_variance, uint, 0644);
MODULE_PARM_DESC(t20_antifog_variance,
	"1: the anti-fog presets also write the Iridix variance nibbles (0x3c8) at the frame-start commit; 0 (default): strength only");
module_param(t20_antifog_ignored, uint, 0444);
MODULE_PARM_DESC(t20_antifog_ignored,
	"anti-fog requests that found the Iridix block disabled");
module_param_named(t20_antifog_level, t20_antifog_level, uint, 0444);
MODULE_PARM_DESC(t20_antifog_level,
	"last accepted anti-fog level (0 off, 1 strong, 2 medium, 3 weak)");

/* 0 on success, -EINVAL for a level above 3; the value is applied by the AE path */
int t20_antifog_request(uint32_t level)
{
	if (level > 3)
		return -EINVAL;
	t20_antifog_level = level;
	t20_antifog_gen++;
	return 0;
}

static void t20_antifog_apply(void)
{
	static const uint8_t strength[4] = { 0, 0xff, 0xc0, 0x80 };
	static const uint8_t variance[4] = { 0, 0x00, 0x44, 0x77 };
	uint32_t gen = t20_antifog_gen;
	uint32_t level;

	if (gen == t20_antifog_seen_gen)
		return;
	level = t20_antifog_level;
	t20_antifog_seen_gen = gen;
	if (level > 3)
		level = 0;

	if (level == 0) {
		if (!t20_antifog_on)
			return;
		/* manual Iridix only if this path switched it on */
		if (!t20_antifog_prev_manual)
			stab.global_manual_iridix = 0;
		if (stab.global_maximum_iridix_strength == 0xff)
			stab.global_maximum_iridix_strength = t20_antifog_saved_max;
		t20_antifog_on = 0;
		if (t20_antifog_variance)
			t20_antifog_hw_want = 0x100 | 0x00;
		return;
	}

	if (!(APICAL_READ_32(0x3c0) & 1)) {
		t20_antifog_ignored++;
		return;
	}
	if (!t20_antifog_on) {
		t20_antifog_prev_manual = stab.global_manual_iridix;
		t20_antifog_saved_max = stab.global_maximum_iridix_strength;
	}
	stab.global_iridix_strength_target = strength[level];
	stab.global_maximum_iridix_strength = 0xff;
	stab.global_manual_iridix = 1;
	t20_antifog_on = level;
	if (t20_antifog_variance)
		t20_antifog_hw_want = 0x300 | variance[level];
}

/* frame-start IRQ 0 (apical_isp_process_interrupt) */
static void t20_antifog_hw_apply(void)
{
	uint32_t want = t20_antifog_hw_want;
	uint32_t cur;

	if (!(want & 0x100))
		return;
	t20_antifog_hw_want = 0;
	if (!(APICAL_READ_32(0x3c0) & 1))
		return;
	cur = APICAL_READ_32(0x3c8);
	if (want & 0x200) {
		if (!t20_antifog_var_valid) {
			t20_antifog_var_saved = (uint8_t)cur;
			t20_antifog_var_valid = 1;
		}
		APICAL_WRITE_32(0x3c8, (cur & 0xffffff00) | (want & 0xff));
	} else if (t20_antifog_var_valid) {
		APICAL_WRITE_32(0x3c8, (cur & 0xffffff00) | t20_antifog_var_saved);
		t20_antifog_var_valid = 0;
	}
}

/*
 * Beyond vendor (T10/T20): lens-shading scale (IMP_ISP_Tuning_
 * SetMeshShadingScale, vendor libimp 3.12.0 0x62930).  The vendor function
 * writes the 3-bit "mesh scale" field of the mesh-shading register 0x380
 * (bits 2..4: reg = (reg & ~0x1c) | ((scale << 2) & 0x1c)) straight through
 * its userspace register mapping, returns 0, and -1 when tuning is not
 * enabled.  The public enum is 0..3 (L, M, H, U); the hardware field takes
 * 0..7 (default 1), larger values are refused here instead of being masked.
 *
 * The control validates the value and stores it; the write itself is done
 * at the frame-end interrupt (apical_isp_process_interrupt, bit 0), i.e.
 * between two frames, and only the 3-bit field is touched.  Like the vendor
 * register write it is lost when the firmware reloads its register sequence
 * (resolution or WDR switch): the application sends it again.
 * Device test pending (host harness: tests/t20_fw "lens-shading scale").
 */
volatile uint32_t t20_mesh_scale_req;	/* bit 8 pending, bits 0..2 value */
uint32_t t20_mesh_scale_cur = 0xff;	/* last value written, 0xff = none */
module_param(t20_mesh_scale_cur, uint, 0444);
MODULE_PARM_DESC(t20_mesh_scale_cur,
	"lens-shading scale last written by SetMeshShadingScale (255 = none)");

/* 0 on success, -EINVAL above 7 */
int t20_mesh_scale_request(uint32_t scale)
{
	if (scale > 7)
		return -EINVAL;
	t20_mesh_scale_req = 0x100 | scale;
	return 0;
}

static void t20_mesh_scale_hw_apply(void)
{
	uint32_t req = t20_mesh_scale_req;
	uint32_t cur;

	if (!(req & 0x100))
		return;
	t20_mesh_scale_req = 0;
	cur = APICAL_READ_32(0x380);
	APICAL_WRITE_32(0x380, (cur & 0xffffffe3) | ((req & 7) << 2));
	t20_mesh_scale_cur = req & 7;
}

/*
 * Beyond vendor (T10/T20): DPC and DRC strength.  The stock tuning switch
 * has no case for the TISP DPC-ratio and DRC-ratio controls the T21/T23/
 * T31 libimp sends; the hardware blocks exist (raw-frontend dynamic defect
 * pixel: threshold 0x1cc, HP-mask slope 0x1d4; Iridix: strength from
 * iridix_update()).  128 is neutral (the IQ-driven values, identical to
 * stock), so nothing changes until a ratio is set.
 *
 *  - DPC: below 128 the threshold moves towards 4095 and the slope towards
 *    0 (0 = no correction), above 128 the threshold moves towards 1 and the
 *    slope towards 4095 (same shape as the OEM T23 tisp_s_dpc_str_internal
 *    threshold scaling).
 *  - DRC: the auto Iridix strength (after the IQ min/max clamp) is scaled
 *    by ratio/128 below 128 (0 = no local tone mapping) and moves linearly
 *    towards full strength (255) above 128.  Manual Iridix (antifog/defog,
 *    DRC MANUAL) is left alone.
 */
uint32_t t20_dpc_ratio = 128;
uint32_t t20_drc_ratio = 128;
uint32_t t20_defog_floor;	/* 0 = off, else minimum auto Iridix strength */
uint16_t t20_dpc_raw_slope;
uint16_t t20_dpc_raw_thresh;
int t20_dpc_raw_valid;

static int32_t t20_dpc_scale_thresh(uint32_t v)
{
	uint32_t s = t20_dpc_ratio;

	if (s == 128)
		return v;
	if (s < 128)
		return v + ((0xfff - v) * (128 - s) >> 7);
	v = (v * (256 - s)) >> 7;
	return v ? v : 1;
}

static int32_t t20_dpc_scale_slope(uint32_t v)
{
	uint32_t s = t20_dpc_ratio;

	if (s == 128)
		return v;
	if (s < 128)
		return (v * s) >> 7;
	return v + ((0xfff - v) * (s - 128) >> 7);
}

/* Called from the tuning ioctl: re-write the registers from the last
 * gain-interpolated values so the new ratio acts before the next gain
 * change. */
void t20_dpc_apply_ratio(void)
{
	unsigned long flags;

	if (!t20_dpc_raw_valid)
		return;
	/*
	 * dynamic_dpc_strength_calculate rewrites the same two registers from
	 * the firmware's frame path: keep the read-modify-writes in one piece
	 * (interrupts off, uniprocessor), so neither tears the other's word.
	 */
	local_irq_save(flags);
	APICAL_WRITE_32(0x1d4, (APICAL_READ_32(0x1d4) & 0xfffff000) |
		(t20_dpc_scale_slope(t20_dpc_raw_slope) & 0xfff));
	APICAL_WRITE_32(0x1cc, (APICAL_READ_32(0x1cc) & 0xfffff000) |
		(t20_dpc_scale_thresh(t20_dpc_raw_thresh) & 0xfff));
	local_irq_restore(flags);
}

/* WHOLE_DRIVER_CANDIDATE fn_000000000002e7e0 origin=model_output original=dynamic_dpc_strength_calculate */
int32_t dynamic_dpc_strength_calculate(int32_t *fsm)
{
    int32_t *ctx = *fsm;
    int32_t gain_again = *(int32_t *)((char *)ctx + 0x2cc);
    int32_t gain_dgain = *(int32_t *)((char *)ctx + 0x2d0);
    int32_t gain_isp = *(int32_t *)((char *)ctx + 0x2d4);
    int32_t reg_slope = APICAL_READ_32(0x1d4);
    int32_t reg_thresh = APICAL_READ_32(0x1cc);
    int32_t *inner = *fsm;
    uint32_t wdr_mode = (uint32_t)*(uint8_t *)((char *)inner + 0x1524);
    int32_t slope;
    int32_t thresh;

    if (wdr_mode != 3) {
        int32_t slope_hdr = _GET_HDR_TABLE_INDEX(0x88, (int32_t)wdr_mode);
        int32_t *inner2 = *fsm;
        uint32_t wdr_mode2 = (uint32_t)*(uint8_t *)((char *)inner2 + 0x1524);
        int32_t thresh_hdr = _GET_HDR_TABLE_INDEX(0x8d, (int32_t)wdr_mode2);
        int16_t *slope_table = (int16_t *)_GET_MOD_ENTRY16_PTR(slope_hdr);
        int32_t slope_rows = _GET_ROWS(slope_hdr);
        int16_t *thresh_table = (int16_t *)_GET_MOD_ENTRY16_PTR(thresh_hdr);
        int32_t thresh_rows = _GET_ROWS(thresh_hdr);
        int32_t sum = gain_again + gain_dgain + gain_isp;
        uint16_t shifted = (uint16_t)(sum >> 8);
        slope = (int32_t)calc_modulation_u16(shifted, slope_table, slope_rows);
        thresh = (int32_t)calc_modulation_u16(shifted, thresh_table, thresh_rows);
    } else {
        slope = reg_slope;
        thresh = reg_thresh;
    }

    t20_dpc_raw_slope = (uint16_t)(slope & 0xfff);
    t20_dpc_raw_thresh = (uint16_t)(thresh & 0xfff);
    t20_dpc_raw_valid = 1;
    slope = t20_dpc_scale_slope(t20_dpc_raw_slope);
    thresh = t20_dpc_scale_thresh(t20_dpc_raw_thresh);

    int32_t cur_slope = APICAL_READ_32(0x1d4);
    int32_t new_slope = (slope & 0xfff) | (cur_slope & 0xfffff000);
    APICAL_WRITE_32(0x1d4, (uint32_t)new_slope);

    int32_t cur_thresh = APICAL_READ_32(0x1cc);
    int32_t new_thresh = (thresh & 0xfff) | (cur_thresh & 0xfffff000);
    return APICAL_WRITE_32(0x1cc, (uint32_t)new_thresh);
}

/* WHOLE_DRIVER_CANDIDATE fn_000000000002e974 origin=model_output original=stitching_error_calculate */
uint32_t stitching_error_calculate(int32_t *fsm)
{
    int32_t *base = *(int32_t **)fsm;
    uint32_t sum;
    uint32_t *entry;
    uint32_t rows;
    uint32_t mod;
    uint32_t status;

    sum = (uint32_t)base[0x2cc / 4] + (uint32_t)base[0x2d0 / 4] + (uint32_t)base[0x2d4 / 4];
    entry = _GET_MOD_ENTRY16_PTR(0xc9);
    rows = _GET_ROWS(0xc9);
    sum = (sum >> 8) & 0xffff;
    mod = calc_modulation_u16(sum, entry, rows);

    status = (uint32_t)(uint8_t)base[0x1524 / 4];

    if (status == 1 || status == 3) {
        uint32_t cur = APICAL_READ_32(0x254);
        return APICAL_WRITE_32(0x254, (cur & 0xffff0000u) | mod);
    }
    return status;
}

/* WHOLE_DRIVER_CANDIDATE fn_000000000002ea5c origin=fragment_seed original=sinter_strength_calculate */
static int32_t sinter_strength_calculate_recovered(uintptr_t state_addr)
{
    return sinter_strength_calculate((struct tx_isp_t20_nr_state *)state_addr);
}

/* T20 APICAL spatial-denoise modulation, reconstructed from the OEM image. */
int32_t sinter_strength_calculate(struct tx_isp_t20_nr_state *state)
{
	struct tx_isp_t20_nr_owner_view *owner = state->isp;
	u16 strength;
	u16 gain = (u16)((owner->sensor_analog_gain +
		owner->sensor_digital_gain + owner->isp_digital_gain) >> 8);
	u8 log_ratio = log16(owner->exposure_ratio);

	if (stab.global_manual_sinter) {
		strength = stab.global_sinter_threshold_target;
	} else {
		int strength_idx = _GET_HDR_TABLE_INDEX(
			T20_CAL_SINTER_STRENGTH_START, owner->wdr_mode);
		int strength1_idx = _GET_HDR_TABLE_INDEX(
			T20_CAL_SINTER_STRENGTH1_START, owner->wdr_mode);
		int thresh1_idx = _GET_HDR_TABLE_INDEX(
			T20_CAL_SINTER_THRESH1_START, owner->wdr_mode);
		int thresh4_idx = _GET_HDR_TABLE_INDEX(
			T20_CAL_SINTER_THRESH4_START, owner->wdr_mode);
		const u16 *table;
		u32 value;

		table = (void *)(uintptr_t)_GET_MOD_ENTRY16_PTR(strength_idx);
		value = calc_adjust_modulation_u16(gain, stab.global_minimum_sinter_strength, stab.global_maximum_sinter_strength,
			(uintptr_t)table, _GET_ROWS(strength_idx));
		strength = min_t(u32, value, 0xff);
		stab.global_sinter_threshold_target = strength;

		table = (void *)(uintptr_t)_GET_MOD_ENTRY16_PTR(strength1_idx);
		value = calc_modulation_u16(gain, (u16 *)table,
			_GET_ROWS(strength1_idx));
		APICAL_WRITE_32(0x2b0,
			(APICAL_READ_32(0x2b0) & 0xffffff00) | (value & 0xff));

		table = (void *)(uintptr_t)_GET_MOD_ENTRY16_PTR(thresh1_idx);
		value = calc_modulation_u16(gain, (u16 *)table,
			_GET_ROWS(thresh1_idx));
		APICAL_WRITE_32(0x290,
			(APICAL_READ_32(0x290) & 0xff00ffff) |
			((value & 0xff) << 16));
		APICAL_WRITE_32(0x298,
			(APICAL_READ_32(0x298) & 0xff00ffff) |
			((value & 0xff) << 16));

		table = (void *)(uintptr_t)_GET_MOD_ENTRY16_PTR(thresh4_idx);
		value = calc_modulation_u16(gain, (u16 *)table,
			_GET_ROWS(thresh4_idx));
		APICAL_WRITE_32(0x294,
			(APICAL_READ_32(0x294) & 0xff00ffff) |
			((value & 0xff) << 16));
		APICAL_WRITE_32(0x29c,
			(APICAL_READ_32(0x29c) & 0xff00ffff) |
			((value & 0xff) << 16));
	}

	state->sinter_strength_base = strength;
	state->sinter_long = strength;
	if (owner->wdr_mode != 3)
		state->sinter_long = (s16)strength - (s16)log_ratio + 0x60;
	if (state->sinter_long < 0)
		state->sinter_long = 0;
	state->sinter_short = strength;
	return state->sinter_long;
}

/* WHOLE_DRIVER_CANDIDATE fn_000000000002ed34 origin=model_output original=temper_strength_calculate */
static uint32_t temper_strength_calculate_recovered(int32_t *fsm)
{
    void *owner = *(void **)fsm;
    uint32_t log_val = log16(*(uint16_t *)((char *)owner + 0x2ca));
    uint32_t *log_offset = log_val - 0x60;
    uint32_t log_offset16 = (int16_t)log_offset;
    uint32_t threshold;

    if (stab.global_manual_temper) {
        threshold = stab.global_temper_threshold_target;
    } else {
        void *owner2 = *(void **)fsm;
        uint32_t sum = (*(int32_t *)((char *)owner2 + 0x2cc) +
                        *(int32_t *)((char *)owner2 + 0x2d0) +
                        *(int32_t *)((char *)owner2 + 0x2d4));
        uint32_t shifted = (uint16_t)(sum >> 8);
        uint32_t mod_entry = _GET_MOD_ENTRY16_PTR(0xcd);
        uint32_t rows = _GET_ROWS(0xcd);
        uint32_t calc_result = calc_adjust_modulation_u16(shifted,
                                                          stab.global_minimum_temper_strength,
                                                          stab.global_maximum_temper_strength,
                                                          mod_entry,
                                                          rows);
        stab.global_temper_threshold_target = (uint8_t)calc_result;
        if (calc_result >= 0x100)
            threshold = 0xff;
        else
            threshold = calc_result;
    }

    *(uint16_t *)((char *)fsm + 0x1e) = (uint16_t)threshold;

    int32_t delta = 0;
    if ((uint32_t)log_offset16 < threshold)
        delta = (int16_t)threshold - (int16_t)log_offset;

    uint32_t gain = *(uint16_t *)((char *)owner + 0x2ca);
    *(uint16_t *)((char *)fsm + 0x12) = (uint16_t)threshold;
    uint32_t scale = *(uint8_t *)((char *)fsm + 0x1a);
    *(uint16_t *)((char *)fsm + 0x10) = (uint16_t)delta;
    *(uint8_t *)((char *)fsm + 0x19) = (uint8_t)(((int32_t)scale * (int32_t)gain) >> 6);

    uint32_t result = *(uint16_t *)((char *)owner + 0x2ca);
    if (result != 0) {
        *(uint8_t *)((char *)fsm + 0x18) = (uint8_t)((uintptr_t)&calibration_luxhigh_lut / (int32_t)result);
    }

    return result;
}

uint32_t temper_strength_calculate(struct tx_isp_t20_nr_state *state)
{
	struct tx_isp_t20_nr_owner_view *owner = state->isp;
	s16 log_delta = (s16)((u16)log16(owner->exposure_ratio) - 0x60);
	u16 strength;

	if (stab.global_manual_temper) {
		strength = stab.global_temper_threshold_target;
	} else {
		const u16 *table = (void *)(uintptr_t)
			_GET_MOD_ENTRY16_PTR(T20_CAL_TEMPER_STRENGTH);
		u16 gain = (u16)((owner->sensor_analog_gain +
			owner->sensor_digital_gain + owner->isp_digital_gain) >> 8);
		u32 value = calc_adjust_modulation_u16(gain, stab.global_minimum_temper_strength, stab.global_maximum_temper_strength,
			(uintptr_t)table, _GET_ROWS(T20_CAL_TEMPER_STRENGTH));

		stab.global_temper_threshold_target = value;
		strength = min_t(u32, value, 0xff);
	}

	state->temper_strength = strength;
	state->temper_short = strength;
	state->temper_long =
		(u32)(s32)log_delta < strength ? strength - log_delta : 0;
	state->temper_scaled =
		(u8)(((u32)state->temper_factor * owner->exposure_ratio) >> 6);
	if (owner->exposure_ratio)
		state->temper_ratio = 0x3000 / owner->exposure_ratio;

	return owner->exposure_ratio;
}

/* WHOLE_DRIVER_CANDIDATE fn_000000000002ee9c origin=model_output original=noise_reduction_hw_init */
int32_t noise_reduction_hw_init(void)
{
	uint32_t (*read_fn)(uint32_t) = APICAL_READ_32;
	uint32_t (*write_fn)(uint32_t, uint32_t) = APICAL_WRITE_32;
	uint32_t v;

	v = read_fn(0x2c0);
	write_fn(0x2c0, v & 0xfffffffe);
	v = read_fn(0xa00);
	return write_fn(0xa00, v & 0xfffeffff);
}

/* WHOLE_DRIVER_CANDIDATE fn_000000000002ef04 origin=model_output original=noise_reduction_initialize */
static int32_t noise_reduction_initialize_recovered(void *fsm)
{
    uint8_t *base = (uint8_t *)fsm;
    uint32_t val;
    uint8_t byte_val;
    uint32_t rows;
    uint32_t *lut_ptr;
    uint32_t last_entry;

	base[0x22] = 1;
	base[0x23] = 1;
	base[0x1b] = 0xf;
	base[0x1c] = 0xf;
    *(uint16_t *)(base + 0x1e) = 0xf;
    *(uint16_t *)(base + 0x20) = 0xf;

    lut_ptr = (uint32_t *)_GET_MOD_ENTRY16_PTR(0xcd);
    byte_val = *(uint8_t *)(lut_ptr + 2);
    stab.global_minimum_temper_strength = byte_val;

    lut_ptr = (uint32_t *)_GET_MOD_ENTRY16_PTR(0xcd);
    rows = _GET_ROWS(0xcd);
    last_entry = (uintptr_t)lut_ptr + ((rows - 1) << 2);
    byte_val = *(uint8_t *)(last_entry + 2);
    stab.global_maximum_temper_strength = byte_val;

    val = (uint32_t)_GET_USHORT_PTR(0x10a);
    byte_val = *(uint8_t *)val;

    val = APICAL_READ_32(0x448) & 0xffffff00;
    val |= byte_val;

    return APICAL_WRITE_32(0x448, val);
}

int32_t noise_reduction_initialize(void *fsm)
{
	struct tx_isp_t20_nr_state *state = fsm;
	const u16 *table = (void *)(uintptr_t)
		_GET_MOD_ENTRY16_PTR(T20_CAL_TEMPER_STRENGTH);
	const u16 *temper_recursion = (void *)(uintptr_t)
		_GET_USHORT_PTR(T20_CAL_TEMPER_RECURSION_LIMIT);
	u32 rows = _GET_ROWS(T20_CAL_TEMPER_STRENGTH);
	u32 value;

	BUILD_BUG_ON(sizeof(*state) != 0x24);
	BUILD_BUG_ON(offsetof(struct tx_isp_t20_nr_owner_view,
		sensor_analog_gain) != 0x2cc);
	BUILD_BUG_ON(offsetof(struct tx_isp_t20_nr_owner_view, wdr_mode) !=
		0x1524);
	if (!table || !temper_recursion || !rows)
		return -EINVAL;

	state->update_sinter = 1;
	state->update_temper = 1;
	state->sinter_log_offset = 0xf;
	state->sinter_strength = 0xf;
	state->temper_strength = 0xf;
	state->sinter_strength_base = 0xf;

	/* Modulation entries are packed { u16 gain, u16 value }. */
	stab.global_minimum_temper_strength = table[1];
	stab.global_maximum_temper_strength = table[(rows - 1) * 2 + 1];

	value = APICAL_READ_32(0x448) & 0xffffff00;
	return APICAL_WRITE_32(0x448,
		value | (*(const u8 *)temper_recursion & 0xff));
}

/* WHOLE_DRIVER_CANDIDATE fn_000000000002efd8 origin=model_output original=noise_reduction_update */
